#include <cstdio>
#include <cstdlib>
#include <string>
#include <sstream>
#include <random>
static std::string s6(double v){ std::ostringstream o; o<<v; return o.str(); }
static std::string s6f(float v){ std::ostringstream o; o<<v; return o.str(); }
int main(){
    std::mt19937 rng(7);
    std::uniform_real_distribution<float> d(0.f,1.f);
    int found=0;
    for(long i=0;i<3000000 && found<10;i++){
        float r=d(rng),g=d(rng),b=d(rng);
        // float pipeline
        float ir=1.0f-r, ig=1.0f-g, ib=1.0f-b;
        float lf=0.2126f*r+0.7152f*g+0.0722f*b;
        // double pipeline
        double dr=1.0-(double)r, dg=1.0-(double)g, db=1.0-(double)b;
        double ld=0.2126*(double)r+0.7152*(double)g+0.0722*(double)b;
        std::string A=s6f(ir)+" "+s6f(ig)+" "+s6f(ib)+" "+s6f(lf);
        std::string B=s6(dr)+" "+s6(dg)+" "+s6(db)+" "+s6(ld);
        if(A!=B){ printf("%.9g %.9g %.9g | float: %s | double: %s\n",r,g,b,A.c_str(),B.c_str()); found++; }
    }
    return 0;
}
EOF
