#include <cstdio>
#include <sstream>
#include <string>
#include <random>
static std::string s(float v){ std::ostringstream o; o<<v; return o.str(); }
int main(){
    std::mt19937 rng(12345);
    std::uniform_real_distribution<float> d(0.f,1.f);
    int f=0;
    for(long i=0;i<8000000 && f<12;i++){
        float r=d(rng),g=d(rng),b=d(rng);
        float A = 0.2126f*r + 0.7152f*g + 0.0722f*b;                     // pure float, left-assoc
        float B = (float)(0.2126*(double)r + 0.7152*(double)g + 0.0722*(double)b); // double then round
        float C = 0.2126f*r + (0.7152f*g + 0.0722f*b);                    // float, right-assoc
        std::string a=s(A),b2=s(B),c=s(C);
        if(a!=b2 || a!=c){
            printf("%.9g %.9g %.9g | Afl=%s Bdbl=%s Cra=%s\n",r,g,b,a.c_str(),b2.c_str(),c.c_str());
            f++;
